def followup_view(inputs, prior):
    packet=inputs.get('eleventh_period_followup')
    if packet is None:return None
    if packet['version']!=1 or packet['content_digest']!=digest({k:v for k,v in packet.items()if k!='content_digest'}):raise ValueError('eleventh period packet changed')
    if prior is None or prior['counts']['after']!=86 or packet['prior_digest']!=digest(prior):raise ValueError('eleventh period prior changed')
    market=inputs['current_extension']['market_inputs']
    if packet['market_digest']!=digest(market):raise ValueError('eleventh period market changed')
    sources={s['announcement_id']:s for s in packet['sources']}
    if len(sources)!=18 or len(packet['sources'])!=18 or set(sources)!=set(SOURCE_BINDINGS):raise ValueError('eleventh period source set changed')
    if packet['visual_read']!=VISUAL:raise ValueError('eleventh period visual scope changed')
    for aid,s in sources.items():
        if {k:s.get(k)for k in SOURCE_BINDINGS[aid]}!=SOURCE_BINDINGS[aid]or not s['protected_gate_passed']:raise ValueError('eleventh period source binding changed')
        if s['published_on']>'2026-11-19':raise ValueError('eleventh period future source')
        if set(s['selected_pages'])!={str(n)for n in range(1,s['pages']+1)}or len(s['page_hashes'])!=s['pages']:raise ValueError('eleventh period pages missing')
        for n,t in s['selected_pages'].items():
            if sha256(t.encode()).hexdigest()!=s['page_hashes'][int(n)-1]:raise ValueError('eleventh period page changed')
    for row in FINANCIAL:
        yoy=((D(row['h1_yuan'])-D(row['prior_h1_yuan']))/abs(D(row['prior_h1_yuan']))*100).quantize(D('.01'),rounding=ROUND_HALF_UP)
        if yoy!=D(row['h1_yoy_pct']):raise ValueError('eleventh period H1 arithmetic changed')
        if D(row['nine_month_yuan'])-D(row['h1_yuan'])!=D(row['quarter_yuan']):raise ValueError('eleventh period quarter bridge changed')
        if row['reported_quarter_yuan']is not None and D(row['quarter_yuan'])!=D(row['reported_quarter_yuan']):raise ValueError('eleventh period reported quarter changed')
        for aid,page,keys in [(row['h1_source'],row['h1_page'],['h1_yuan','prior_h1_yuan']),(row['q3_source'],row['q3_page'],['nine_month_yuan'])]:
            text=sources[aid]['selected_pages'][str(page)].replace(',','')
            if aid==SCAN['source']:
                if page!=SCAN['page'] or text or sources[aid]['sha256']!=SCAN['pdf_sha256']:raise ValueError('eleventh period scan binding changed')
                index=['revenue','parent_profit','deducted_profit','operating_cash'].index(row['metric'])
                if row['nine_month_yuan']!=SCAN['nine'][index] or row['reported_quarter_yuan']!=SCAN['quarter'][index]:raise ValueError('eleventh period scan transcription changed')
                if not any(r['source']==aid and r['page']==page and r['image_sha256']==SCAN['render_sha256']for r in VISUAL):raise ValueError('eleventh period scan visual missing')
            elif any(row[k]not in text for k in keys):raise ValueError('eleventh period financial source changed')
    from st_regime_comparison import build
    windows=event_windows(market,build(market)['daily'],list(sources.values()),allow_nontraded=True,allow_missing=True)
    if digest(windows)!=packet['event_windows_digest']:raise ValueError('eleventh period windows changed')
    return {'through':'2026-11-19','title':'申请、签约与财报，哪些真正改变了原判断？','answer':'天圣处罚条件跨过时间门槛后再次申请，仍待交易所批准；美芝从招募走到签约和庭外表决，但司法程序、剩余投资款和净资产修复仍要分别核。中装7月仍补材料，不能外推为11月状态；四家第三季度经营现金差额均为净流出。程序有进展，与经营已经恢复，是两个问题。','chains':CHAINS,'financial_bridge':FINANCIAL,'event_windows':windows,'sources':[{k:v for k,v in s.items()if k not in ['raw_item','selected_pages','page_hashes']}for s in sources.values()],'counts':{'files':18,'new_files':18,'reused_files':0,'pages':816,'new_pages':816,'viewed_pages':len(VISUAL),'initial_coverage':86,'complete_windows':sum(w['status']=='complete'for e in windows for w in e['windows']),'unfinished_windows':sum(w['status']=='unfinished'for e in windows for w in e['windows']),'stock_endpoint_gaps':sum(w['stock_pct']is None for e in windows for w in e['windows'])},'boundary':'18份816页仅选关键页核读，不称逐页审阅全文；87条目录不认证所有期间催化穷尽。54市场窗口45满期、9未满，股票端点无空值；58端点跨渠道核对，不能认证上游完全独立。四项单季经营现金均为累计差额推算；中设用重述后的比较期。美芝扫描三季报第2页人工转录，保留原空提取与图像校验值。广州案合计含原告自身费用，不当可收或实收；不同仲裁案不混接。期初覆盖仍86/150、缺64，公告同窗不识别净因果，重复披露不增加经验验证。','method_promotions':0}
